#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    vector<int> z(n, 0);
    z[0] = n;
    int l = 0, rr = 0;
    for (int i = 1; i < n; i++) {
        if (i < rr) z[i] = min(rr - i, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > rr) {
            l = i;
            rr = i + z[i];
        }
    }
    for (int i = 0; i < n; i++) cout << (i ? " " : "") << z[i];
    cout << "\n";

    return 0;
}

